"""French translation of the In the Binder privacy policy.

translate_privacy(html) takes the English privacy.html and returns the French
version. Each English string must appear exactly once, or it raises.
"""

PAIRS = [
    ('<html lang="en">', '<html lang="fr">'),
    ("<title>In the Binder Privacy Policy</title>",
     "<title>Politique de confidentialité d'In the Binder</title>"),
    ('<a href="/"><img src="/logo.png" alt="In the Binder" height="48" style="display:block;margin-bottom:18px"></a>',
     '<a href="/fr/"><img src="/logo.png" alt="In the Binder" height="48" style="display:block;margin-bottom:18px"></a>'),
    ("<h1>In the Binder Privacy Policy</h1>",
     "<h1>Politique de confidentialité d'In the Binder</h1>"),
    ('<p class="meta">Last updated: 16 October 2026</p>',
     '<p class="meta">Dernière mise à jour : 16 octobre 2026</p>'),
    ("<strong>The short version:</strong> your collection lives on your phone. In the Binder has no accounts and no servers that store your data. We never see what you own. Apart from the services listed below, which only receive what they need to answer a request, the only third party that receives data about your device is Google AdMob, which shows the banner ad.",
     "<strong>En résumé :</strong> votre collection reste sur votre téléphone. In the Binder n'a ni comptes ni serveurs qui stockent vos données. Nous ne voyons jamais ce que vous possédez. En dehors des services listés ci-dessous, qui ne reçoivent que ce dont ils ont besoin pour répondre à une requête, le seul tiers qui reçoit des données sur votre appareil est Google AdMob, qui affiche la bannière publicitaire."),
    ("<h2>Who we are</h2>", "<h2>Qui nous sommes</h2>"),
    ('In the Binder is published by R. Iglesias, trading as In the Binder, a sole trader based in England ("we", "us"). For any privacy question, contact <a href="mailto:support@inthebinder.com">support@inthebinder.com</a>.',
     'In the Binder est édité par R. Iglesias, exerçant sous le nom In the Binder, entrepreneur individuel établi en Angleterre (« nous »). Pour toute question de confidentialité, contactez <a href="mailto:support@inthebinder.com">support@inthebinder.com</a>.'),
    ("<h2>What stays on your phone</h2>", "<h2>Ce qui reste sur votre téléphone</h2>"),
    ("<strong>Your collection:</strong> the cards, sealed products and graded slabs you add, with quantities, conditions, grades and certificate numbers. This is stored in the app's own database on your device. So that a lost or replaced phone doesn't mean a lost collection, the app also keeps a small copy of it (your cards, sealed products, price history, price alerts and display settings, never keys or photos) for your phone's own backup. If backup is switched on in your phone's settings, Android saves that copy in your Google account's backup and can bring it back on a new phone, where the app asks you before restoring it. That backup is held by Google under your account; we never receive it. Nothing else the app stores is included. You can turn backup off in your phone's settings.",
     "<strong>Votre collection :</strong> les cartes, produits scellés et slabs gradés que vous ajoutez, avec les quantités, états, notes et numéros de certificat. Tout cela est stocké dans la base de données de l'application, sur votre appareil. Pour qu'un téléphone perdu ou remplacé ne signifie pas une collection perdue, l'application en conserve aussi une petite copie (vos cartes, produits scellés, historique des prix, alertes de prix et réglages d'affichage, jamais de clés ni de photos) pour la sauvegarde de votre téléphone. Si la sauvegarde est activée dans les réglages de votre téléphone, Android enregistre cette copie dans la sauvegarde de votre compte Google et peut la restaurer sur un nouveau téléphone, où l'application vous demande votre accord avant de la rétablir. Cette sauvegarde est détenue par Google sous votre compte ; nous ne la recevons jamais. Rien d'autre de ce que stocke l'application n'y est inclus. Vous pouvez désactiver la sauvegarde dans les réglages de votre téléphone."),
    ("<strong>Settings, theme and visit streak:</strong> also stored on your device (display settings are included in the backup copy described above).",
     "<strong>Réglages, thème et série de visites :</strong> également stockés sur votre appareil (les réglages d'affichage sont inclus dans la copie de sauvegarde décrite ci-dessus)."),
    ("<strong>Camera and photos:</strong> the camera is used only while the scanner is open, to recognise cards on your phone itself. Card recognition runs entirely on the device. Photos are never uploaded. Photos you choose to import are read on the device in the same way.",
     "<strong>Caméra et photos :</strong> la caméra n'est utilisée que lorsque le scanner est ouvert, pour reconnaître les cartes sur votre téléphone lui-même. La reconnaissance des cartes se fait entièrement sur l'appareil. Les photos ne sont jamais envoyées. Les photos que vous choisissez d'importer sont lues sur l'appareil de la même façon."),
    ("<strong>Scanner memory:</strong> when you confirm a scanned card, the scanner keeps a small numeric fingerprint of that photo (not the photo itself) on your phone, so it recognises your cards faster next time. It never leaves your device, and you can erase it in Settings, under Scanner memory.",
     "<strong>Mémoire du scanner :</strong> lorsque vous confirmez une carte scannée, le scanner conserve sur votre téléphone une petite empreinte numérique de cette photo (pas la photo elle-même), pour reconnaître vos cartes plus vite la fois suivante. Elle ne quitte jamais votre appareil, et vous pouvez l'effacer dans les Réglages, sous Mémoire du scanner."),
    ("<strong>NFC:</strong> used only when you tap a graded slab's chip, to read its certificate number.",
     "<strong>NFC :</strong> utilisé uniquement lorsque vous approchez la puce d'un slab gradé, pour lire son numéro de certificat."),
    ("<strong>Error log:</strong> the app keeps a short list of its own recent errors (error messages only, never your collection or photos) on your phone. It is only sent if you choose \"Send feedback\" in Settings, which opens an email you can read and edit before sending.",
     "<strong>Journal d'erreurs :</strong> l'application conserve sur votre téléphone une courte liste de ses erreurs récentes (messages d'erreur uniquement, jamais votre collection ni vos photos). Elle n'est envoyée que si vous choisissez « Envoyer un retour » dans les Réglages, ce qui ouvre un e-mail que vous pouvez lire et modifier avant l'envoi."),
    ("Uninstalling the app deletes all of this from your phone. A copy in your phone's Google backup, if there is one, is managed by Google and can be removed from your Google account's backup settings. You can export your collection at any time from Settings.",
     "Désinstaller l'application supprime tout cela de votre téléphone. Une copie dans la sauvegarde Google de votre téléphone, s'il y en a une, est gérée par Google et peut être supprimée depuis les réglages de sauvegarde de votre compte Google. Vous pouvez exporter votre collection à tout moment depuis les Réglages."),
    ("<h2>What leaves your phone</h2>", "<h2>Ce qui quitte votre téléphone</h2>"),
    ("<strong>Card prices and images:</strong> to show prices and pictures, the app downloads the day's public card prices from our data repository on GitHub (raw.githubusercontent.com), which copies them from the Pokémon TCG API (pokemontcg.io) once a day. If that copy isn't available, the app asks pokemontcg.io directly. Card images come from pokemontcg.io's image servers. These requests ask for public set and card information. They don't include your collection or anything that identifies you, beyond the IP address every internet request carries.",
     "<strong>Prix et images des cartes :</strong> pour afficher les prix et les images, l'application télécharge les prix publics du jour depuis notre dépôt de données sur GitHub (raw.githubusercontent.com), qui les copie une fois par jour depuis l'API Pokémon TCG (pokemontcg.io). Si cette copie n'est pas disponible, l'application interroge directement pokemontcg.io. Les images des cartes proviennent des serveurs d'images de pokemontcg.io. Ces requêtes demandent des informations publiques sur les séries et les cartes. Elles n'incluent pas votre collection ni rien qui vous identifie, au-delà de l'adresse IP que porte toute requête internet."),
    ("<strong>Other card games (One Piece, Lorcana, Dragon Ball, Magic, Yu-Gi-Oh!):</strong> the first time you open one of these games, the app downloads its public card list and scanner reference data from our data repository on GitHub (github.com and raw.githubusercontent.com), and then checks for updates and the day's market prices about once a day. That data is built from TCGplayer's public product information. Card pictures are loaded from TCGplayer's image server (tcgplayer-cdn.tcgplayer.com). These requests ask only for public card information and carry nothing about you or your collection, beyond the IP address every internet request carries.",
     "<strong>Autres jeux de cartes (One Piece, Lorcana, Dragon Ball, Magic, Yu-Gi-Oh!) :</strong> la première fois que vous ouvrez l'un de ces jeux, l'application télécharge sa liste de cartes publiques et les données de référence du scanner depuis notre dépôt de données sur GitHub (github.com et raw.githubusercontent.com), puis vérifie les mises à jour et les prix du marché du jour environ une fois par jour. Ces données sont construites à partir des informations produit publiques de TCGplayer. Les images des cartes sont chargées depuis le serveur d'images de TCGplayer (tcgplayer-cdn.tcgplayer.com). Ces requêtes ne demandent que des informations publiques sur les cartes et ne transportent rien sur vous ni votre collection, au-delà de l'adresse IP que porte toute requête internet."),
    ("<strong>Exchange rates:</strong> to show prices in your currency, the app fetches the European Central Bank's daily reference rates from Frankfurter (frankfurter.app) at most once a day. The request asks only for the rates and carries nothing about you or your collection, beyond the IP address every internet request carries.",
     "<strong>Taux de change :</strong> pour afficher les prix dans votre devise, l'application récupère les taux de référence quotidiens de la Banque centrale européenne depuis Frankfurter (frankfurter.app), au maximum une fois par jour. La requête ne demande que les taux et ne transporte rien sur vous ni votre collection, au-delà de l'adresse IP que porte toute requête internet."),
    ("<strong>New card data:</strong> once a day the app checks this website for a newer card list and scanner index, and downloads it if there is one. The request carries nothing about you or your collection, beyond the IP address every internet request carries.",
     "<strong>Nouvelles données de cartes :</strong> une fois par jour, l'application vérifie sur ce site s'il existe une liste de cartes et un index de scanner plus récents, et les télécharge le cas échéant. La requête ne transporte rien sur vous ni votre collection, au-delà de l'adresse IP que porte toute requête internet."),
    ("<strong>App updates:</strong> when the app opens, it asks Expo (expo.dev), the service that delivers its small updates, whether a newer version is ready. The request carries the app's version, whether it's running on Android or iPhone, and a random install number created on your phone. That number isn't linked to you or your advertising ID, and it changes if you reinstall the app. Expo uses it to send the right update and count installs.",
     "<strong>Mises à jour de l'application :</strong> à son ouverture, l'application demande à Expo (expo.dev), le service qui diffuse ses petites mises à jour, si une version plus récente est prête. La requête transporte la version de l'application, le fait qu'elle tourne sur Android ou iPhone, et un numéro d'installation aléatoire créé sur votre téléphone. Ce numéro n'est lié ni à vous ni à votre identifiant publicitaire, et il change si vous réinstallez l'application. Expo l'utilise pour envoyer la bonne mise à jour et compter les installations."),
    ("<strong>Sealed product barcodes:</strong> when you scan the barcode of a sealed product (a booster box, a tin) that the app doesn't already know, it first checks a list of sealed-product barcodes downloaded from our data repository on GitHub; nothing is sent for that. Only if the barcode isn't on the list is the barcode number sent to UPCitemdb (upcitemdb.com) to look up the product's name and picture. Only the barcode number is sent.",
     "<strong>Codes-barres des produits scellés :</strong> lorsque vous scannez le code-barres d'un produit scellé (un display, une boîte métal) que l'application ne connaît pas encore, elle vérifie d'abord une liste de codes-barres de produits scellés téléchargée depuis notre dépôt de données sur GitHub ; rien n'est envoyé pour cela. Ce n'est que si le code-barres n'est pas dans la liste que son numéro est envoyé à UPCitemdb (upcitemdb.com) pour retrouver le nom et l'image du produit. Seul le numéro de code-barres est envoyé."),
    ("<strong>PriceCharting import (optional):</strong> if you choose to import your collection from PriceCharting, the app fetches that collection from pricecharting.com using the seller ID or link you enter. Nothing is sent unless you start an import.",
     "<strong>Import PriceCharting (facultatif) :</strong> si vous choisissez d'importer votre collection depuis PriceCharting, l'application récupère cette collection sur pricecharting.com à l'aide de l'identifiant vendeur ou du lien que vous saisissez. Rien n'est envoyé tant que vous ne lancez pas d'import."),
    ("<strong>Grading certificate checks:</strong> the \"Cert\" and \"Verify\" buttons open the grading company's own website (PSA, CGC, Beckett and others) in your browser, with the certificate number in the address, so you can check a slab. That site's own privacy policy applies.",
     "<strong>Vérification des certificats de gradation :</strong> les boutons « Cert » et « Vérifier » ouvrent le site de l'organisme de gradation (PSA, CGC, Beckett et autres) dans votre navigateur, avec le numéro de certificat dans l'adresse, pour que vous puissiez vérifier un slab. La politique de confidentialité de ce site s'applique alors."),
    ("<strong>Shared collection links:</strong> when you share your collection, the whole list is written into the link itself, after the \"#\". That part of a link is never sent to any server, ours included. Whoever opens the link sees the collection; their browser then loads public card pictures and prices the same way the app does.",
     "<strong>Liens de collection partagée :</strong> lorsque vous partagez votre collection, toute la liste est inscrite dans le lien lui-même, après le « # ». Cette partie d'un lien n'est jamais envoyée à aucun serveur, y compris le nôtre. Quiconque ouvre le lien voit la collection ; son navigateur charge ensuite les images et prix publics des cartes de la même façon que l'application."),
    ("<strong>Jev sorting (optional, off unless you turn it on):</strong> if you add your own TypeSafe AI key in Settings and tap \"Sort held PriceCharting items\", the names of those items and the candidate card names are sent to TypeSafe AI (api.typesafe.ai) to pick the matching card. Nothing else is sent, and nothing is sent unless you add a key and tap the button. Your key is stored only on your phone.",
     "<strong>Tri Jev (facultatif, désactivé sauf si vous l'activez) :</strong> si vous ajoutez votre propre clé TypeSafe AI dans les Réglages et appuyez sur « Trier les articles PriceCharting en attente », les noms de ces articles et ceux des cartes candidates sont envoyés à TypeSafe AI (api.typesafe.ai) pour choisir la carte correspondante. Rien d'autre n'est envoyé, et rien n'est envoyé tant que vous n'ajoutez pas de clé et n'appuyez pas sur le bouton. Votre clé est stockée uniquement sur votre téléphone."),
    ("<strong>Advertising (Google AdMob):</strong> the free app shows a banner ad served by Google AdMob. AdMob may collect your device's advertising ID, IP address and information about ad interactions, to show ads, limit repeats, measure performance and prevent fraud. In the UK and EEA you're asked for consent before personalised ads are shown, and you can change that choice at any time. You can also reset or delete your advertising ID in your phone's Google settings. See <a href=\"https://policies.google.com/technologies/partner-sites\">how Google uses data from apps that use its services</a>.",
     "<strong>Publicité (Google AdMob) :</strong> l'application gratuite affiche une bannière publicitaire diffusée par Google AdMob. AdMob peut collecter l'identifiant publicitaire de votre appareil, votre adresse IP et des informations sur vos interactions avec les publicités, afin d'afficher des annonces, limiter les répétitions, mesurer les performances et prévenir la fraude. Au Royaume-Uni et dans l'EEE, votre consentement est demandé avant l'affichage de publicités personnalisées, et vous pouvez modifier ce choix à tout moment. Vous pouvez aussi réinitialiser ou supprimer votre identifiant publicitaire dans les réglages Google de votre téléphone. Voir <a href=\"https://policies.google.com/technologies/partner-sites\">comment Google utilise les données des applis qui recourent à ses services</a>."),
    ("<strong>Buy and sold-price links:</strong> the \"Buy\", \"Sold prices\" and \"Cardmarket\" buttons open TCGplayer, eBay or Cardmarket in your browser. These links may carry an affiliate tag, so we may earn a commission if you buy something. Those sites have their own privacy policies. We receive no personal information from them, only anonymous commission reports.",
     "<strong>Liens d'achat et de prix de vente :</strong> les boutons « Acheter », « Prix de vente » et « Cardmarket » ouvrent TCGplayer, eBay ou Cardmarket dans votre navigateur. Ces liens peuvent porter une balise d'affiliation, donc nous pouvons percevoir une commission si vous achetez quelque chose. Ces sites ont leurs propres politiques de confidentialité. Nous ne recevons d'eux aucune information personnelle, seulement des rapports de commission anonymes."),
    ("<h2>What we don't do</h2>", "<h2>Ce que nous ne faisons pas</h2>"),
    ("<li>We don't sell your data.</li>", "<li>Nous ne vendons pas vos données.</li>"),
    ("<li>We don't run accounts, logins or cloud storage.</li>",
     "<li>Nous n'avons ni comptes, ni connexions, ni stockage dans le cloud.</li>"),
    ("<li>We don't track your location.</li>", "<li>Nous ne suivons pas votre position.</li>"),
    ("<li>We don't read your contacts or files, apart from the photos, backups and spreadsheets you choose to import yourself. Those are read on your phone and never uploaded.</li>",
     "<li>Nous ne lisons ni vos contacts ni vos fichiers, hormis les photos, sauvegardes et tableurs que vous choisissez d'importer vous-même. Ils sont lus sur votre téléphone et jamais envoyés.</li>"),
    ("<h2>Legal basis (UK GDPR)</h2>", "<h2>Base légale (RGPD britannique)</h2>"),
    ("Storing your collection on your own device needs no legal basis from us, because we never receive it. Advertising data is processed by Google on the basis of your consent (for personalised ads) or legitimate interests (for non-personalised ads and fraud prevention).",
     "Le stockage de votre collection sur votre propre appareil ne nécessite aucune base légale de notre part, car nous ne la recevons jamais. Les données publicitaires sont traitées par Google sur la base de votre consentement (pour les publicités personnalisées) ou de l'intérêt légitime (pour les publicités non personnalisées et la prévention de la fraude)."),
    ("<h2>Children</h2>", "<h2>Enfants</h2>"),
    ("In the Binder is intended for collectors aged 13 and over and is not directed at children under 13.",
     "In the Binder est destiné aux collectionneurs de 13 ans et plus et ne s'adresse pas aux enfants de moins de 13 ans."),
    ("<h2>Your rights</h2>", "<h2>Vos droits</h2>"),
    ("You have the right to ask what personal data we hold about you. Because we hold none on our side, most requests are answered by the fact that your data never left your phone. For advertising data, use Google's controls or contact us and we'll help. You can also complain to the UK Information Commissioner's Office at <a href=\"https://ico.org.uk\">ico.org.uk</a>.",
     "Vous avez le droit de demander quelles données personnelles nous détenons à votre sujet. Comme nous n'en détenons aucune de notre côté, la plupart des demandes trouvent leur réponse dans le fait que vos données n'ont jamais quitté votre téléphone. Pour les données publicitaires, utilisez les réglages de Google ou contactez-nous et nous vous aiderons. Vous pouvez aussi déposer une réclamation auprès de l'Information Commissioner's Office britannique sur <a href=\"https://ico.org.uk\">ico.org.uk</a>."),
    ("<h2>Changes</h2>", "<h2>Modifications</h2>"),
    ("If this policy changes, we'll update the date at the top and, for significant changes, mention it in the app.",
     "Si cette politique évolue, nous mettrons à jour la date en haut et, pour les changements importants, nous le signalerons dans l'application."),
    ("In the Binder is an independent app. It is not affiliated with, endorsed or sponsored by Nintendo, Creatures Inc., GAME FREAK inc., The Pokémon Company, Bandai, Disney, Ravensburger, Wizards of the Coast, Konami or any other card publisher. Card names, images and trademarks belong to their respective owners.",
     "In the Binder est une application indépendante. Elle n'est ni affiliée, ni approuvée, ni parrainée par Nintendo, Creatures Inc., GAME FREAK inc., The Pokémon Company, Bandai, Disney, Ravensburger, Wizards of the Coast, Konami ou tout autre éditeur de cartes. Les noms de cartes, images et marques appartiennent à leurs propriétaires respectifs."),
]


def translate_privacy(html):
    for en, fr in PAIRS:
        n = html.count(en)
        if n != 1:
            raise SystemExit("STOP [privacy]: expected 1 of %r, found %d" % (en[:60], n))
        html = html.replace(en, fr)
    return html  # the EN/FR switcher is added by build-fr.py
